content:
/* Reset & Base Styles */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Hiragino Sans", "Hiragino Kaku Gothic ProN", Meiryo, sans-serif;
  --color-primary: #1e40af;
  --color-primary-hover: #1d4ed8;
  --color-primary-light: #eff6ff;
  --color-primary-border: #93c5fd;
  --color-success: #14532d;
  --color-success-bg: #f0fdf4;
  --color-success-border: #4ade80;
  --color-danger: #991b1b;
  --color-danger-bg: #fef2f2;
  --color-danger-border: #f87171;
  --color-bg-base: #f8fafc;
  --color-surface: #ffffff;
  --color-text-main: #0f172a;
  --color-text-sub: #334155;
  --color-text-muted: #64748b;
  --color-border: #cbd5e1;
  --color-border-hover: #94a3b8;
  --focus-outline-color: #2563eb;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-full: 9999px;
  --transition-fast: 0.18s ease;
  --transition-smooth: 0.28s ease;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg-base);
  color: var(--color-text-main);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
}

/* App Wrapper */
.quiz-app {
  min-height: 100vh;
  padding: 24px 16px 48px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  background: radial-gradient(circle at 50% 0%, #e0f2fe 0%, #f8fafc 65%);
}

.quiz-container {
  width: 100%;
  max-width: 680px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* Header & Progress */
.quiz-header {
  text-align: center;
  padding: 8px 0 12px;
}

.header-title {
  font-size: 1.65rem;
  font-weight: 800;
  color: #1e3a8a;
  letter-spacing: -0.02em;
  margin-bottom: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.progress-wrapper {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 14px;
}

.progress-bar-bg {
  width: 100%;
  height: 10px;
  background-color: #e2e8f0;
  border-radius: var(--radius-full);
  overflow: hidden;
  position: relative;
}

.progress-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #3b82f6 0%, #2563eb 100%);
  border-radius: var(--radius-full);
  transition: width var(--transition-smooth);
}

.progress-counter {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-muted);
}

/* Question Card */
.quiz-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.question-category-tag {
  align-self: flex-start;
  display: inline-block;
  font-size: 0.775rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #1d4ed8;
  background-color: var(--color-primary-light);
  border: 1px solid var(--color-primary-border);
  padding: 4px 10px;
  border-radius: var(--radius-full);
}

.question-text {
  font-size: 1.25rem;
  font-weight: 700;
  line-height: 1.5;
  color: var(--color-text-main);
  word-break: break-word;
}

/* Options Grid */
.options-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
}

.option-btn {
  width: 100%;
  text-align: left;
  background: var(--color-surface);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 14px 16px;
  display: flex;
  align-items: center;
  gap: 14px;
  font-family: inherit;
  font-size: 1rem;
  cursor: pointer;
  transition: all var(--transition-fast);
  color: var(--color-text-main);
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.option-btn:hover:not(:disabled) {
  border-color: #60a5fa;
  background-color: #f8fafc;
  transform: translateY(-1px);
  box-shadow: var(--shadow-sm);
}

.option-btn:active:not(:disabled) {
  transform: translateY(0);
}

.option-btn:focus-visible {
  outline: 3px solid var(--focus-outline-color);
  outline-offset: 2px;
}

.option-btn:disabled {
  cursor: default;
}

/* Option States */
.option-btn-default {
  border-color: var(--color-border);
  background-color: var(--color-surface);
}

.option-btn-selected {
  border-color: #2563eb;
  background-color: var(--color-primary-light);
  color: #1e3a8a;
  font-weight: 600;
}

.option-btn-correct {
  border-color: var(--color-success);
  background-color: var(--color-success-bg);
  color: var(--color-success);
  font-weight: 700;
}

.option-btn-wrong {
  border-color: var(--color-danger);
  background-color: var(--color-danger-bg);
  color: var(--color-danger);
  font-weight: 700;
}

.option-index {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background-color: #f1f5f9;
  border: 1px solid var(--color-border);
  color: var(--color-text-main);
  font-size: 0.85rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
}

.option-btn-selected .option-index {
  background-color: #2563eb;
  border-color: #2563eb;
  color: #ffffff;
}

.option-btn-correct .option-index {
  background-color: var(--color-success);
  border-color: var(--color-success);
  color: #ffffff;
}

.option-btn-wrong .option-index {
  background-color: var(--color-danger);
  border-color: var(--color-danger);
  color: #ffffff;
}

.option-text {
  flex: 1;
  line-height: 1.45;
}

/* Feedback Card */
.feedback-card {
  margin-top: 8px;
  padding: 16px 18px;
  border-radius: var(--radius-md);
  background-color: #f8fafc;
  border: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  gap: 8px;
  animation: fadeIn 0.25s ease-out;
}

.feedback-title-correct {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--color-success);
  display: flex;
  align-items: center;
  gap: 6px;
}

.feedback-title-wrong {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--color-danger);
  display: flex;
  align-items: center;
  gap: 6px;
}

.feedback-explanation {
  font-size: 0.95rem;
  line-height: 1.6;
  color: var(--color-text-sub);
}

/* Navigation Buttons */
.next-btn {
  margin-top: 12px;
  width: 100%;
  padding: 14px 20px;
  background: linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%);
  color: #ffffff;
  font-family: inherit;
  font-size: 1.05rem;
  font-weight: 700;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  box-shadow: 0 4px 10px rgba(37, 99, 235, 0.28);
  transition: all var(--transition-fast);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.next-btn:hover {
  background: linear-gradient(135deg, #1d4ed8 0%, #1e40af 100%);
  transform: translateY(-1px);
  box-shadow: 0 6px 14px rgba(37, 99, 235, 0.35);
}

.next-btn:active {
  transform: translateY(0);
}

.next-btn:focus-visible {
  outline: 3px solid var(--focus-outline-color);
  outline-offset: 2px;
}

/* Result Screen */
.result-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 24px;
}

.score-badge {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 4px;
  padding: 18px 36px;
  background: linear-gradient(135deg, #f0fdf4 0%, #e0f2fe 100%);
  border: 2px solid #7dd3fc;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  width: 100%;
  max-width: 320px;
}

.score-number {
  font-size: 3.5rem;
  font-weight: 900;
  color: #0369a1;
  line-height: 1;
}

.score-max {
  font-size: 1.4rem;
  font-weight: 700;
  color: #334155;
}

.score-rank {
  font-size: 1.5rem;
  font-weight: 800;
  color: #0f172a;
  margin-top: -6px;
}

.score-comment {
  font-size: 1rem;
  color: var(--color-text-sub);
  max-width: 460px;
  line-height: 1.6;
}

/* Review Section */
.review-section {
  width: 100%;
  margin-top: 12px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  text-align: left;
}

.review-heading {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--color-text-main);
  border-bottom: 2px solid var(--color-border);
  padding-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.review-item {
  background-color: #f8fafc;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.review-q-title {
  font-size: 0.975rem;
  font-weight: 700;
  color: var(--color-text-main);
  line-height: 1.45;
}

.review-ans-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 0.9rem;
}

.review-correct-text {
  color: var(--color-success);
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 4px;
}

.review-wrong-text {
  color: var(--color-danger);
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 4px;
}

.review-desc {
  font-size: 0.875rem;
  line-height: 1.55;
  color: var(--color-text-sub);
  background-color: #ffffff;
  padding: 10px 12px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--color-border);
  margin-top: 4px;
}

.retry-btn {
  width: 100%;
  max-width: 320px;
  margin-top: 8px;
  padding: 14px 24px;
  background: linear-gradient(135deg, #0f766e 0%, #0d9488 100%);
  color: #ffffff;
  font-family: inherit;
  font-size: 1.05rem;
  font-weight: 700;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  box-shadow: 0 4px 12px rgba(13, 148, 136, 0.28);
  transition: all var(--transition-fast);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.retry-btn:hover {
  background: linear-gradient(135deg, #115e59 0%, #0f766e 100%);
  transform: translateY(-1px);
  box-shadow: 0 6px 16px rgba(13, 148, 136, 0.35);
}

.retry-btn:active {
  transform: translateY(0);
}

.retry-btn:focus-visible {
  outline: 3px solid #0f766e;
  outline-offset: 2px;
}

/* Animations & Responsive */
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 480px) {
  .quiz-app {
    padding: 16px 12px 36px;
  }

  .quiz-card {
    padding: 20px 16px;
    gap: 16px;
  }

  .header-title {
    font-size: 1.4rem;
  }

  .question-text {
    font-size: 1.125rem;
  }

  .option-btn {
    padding: 12px 14px;
    font-size: 0.95rem;
  }

  .result-card {
    padding: 24px 16px;
  }

  .score-number {
    font-size: 2.8rem;
  }

  .score-rank {
    font-size: 1.25rem;
  }
}

export type QuizDifficulty = 'easy' | 'medium' | 'hard';

export interface QuizQuestion {
  readonly id: number;
  readonly question: string;
  readonly options: readonly string[];
  readonly answerIndex: number;
  readonly explanation: string;
  readonly hintCategory: string;
  readonly difficulty?: QuizDifficulty;
  readonly imageUrl?: string;
}

export interface UserAnswer {
  readonly questionId: number;
  readonly selectedIndex: number;
  readonly isCorrect: boolean;
  readonly correctIndex?: number;
  readonly category?: string;
  readonly answeredAt?: number;
}

export interface RankInfo {
  readonly rank: string;
  readonly comment: string;
}

export type QuizRank = RankInfo;

export interface QuizProgress {
  readonly currentIndex: number;
  readonly totalQuestions: number;
  readonly isCompleted: boolean;
  readonly score: number;
}

