/**
 * クイズデータの整合性を検証するヘルパー関数
 * IDの連番性、選択肢の件数、正解インデックスの妥当性をチェックします
 */
export const validateQuizData = (questions: readonly QuizQuestion[]): boolean => {
  return questions.every((q, idx) => {
    const isIdSequential = q.id === idx + 1;
    const hasValidAnswerIndex = q.answerIndex >= 0 && q.answerIndex < q.options.length;
    const hasOptions = q.options.length >= 2;
    return isIdSequential && hasValidAnswerIndex && hasOptions;
  });
};

import { useEffect, useRef } from 'react';
import { QuizQuestion } from '../types';

interface QuizCardProps {
  question: QuizQuestion;
  currentIndex: number;
  totalCount: number;
  selectedOption: number | null;
  isAnswered: boolean;
  onSelectOption?: (index: number) => void;
  onNext?: () => void;
}

const getOptionLabel = (index: number): string => {
  return String.fromCharCode(65 + index);
};

const QuizCard = ({
  question,
  currentIndex,
  totalCount,
  selectedOption,
  isAnswered,
  onSelectOption,
  onNext,
}: QuizCardProps) => {
  const nextButtonRef = useRef<HTMLButtonElement | null>(null);
  const isCorrect = selectedOption !== null && selectedOption === question.answerIndex;

  useEffect(() => {
    if (isAnswered && nextButtonRef.current) {
      nextButtonRef.current.focus();
    }
  }, [isAnswered]);

  const handleSelect = (idx: number) => {
    if (!isAnswered && onSelectOption) {
      onSelectOption(idx);
    }
  };

  const handleNext = () => {
    if (onNext) {
      onNext();
    }
  };

  return (
    <div className="quiz-card">
      <span className="question-category-tag">{question.hintCategory}</span>
      <h2 className="question-text">
        Q{currentIndex + 1}. {question.question}
      </h2>

      <div className="options-grid" role="group" aria-label="選択肢">
        {question.options.map((option, index) => {
          let btnStateClass = 'option-btn-default';
          if (isAnswered) {
            if (index === question.answerIndex) {
              btnStateClass = 'option-btn-correct';
            } else if (index === selectedOption) {
              btnStateClass = 'option-btn-wrong';
            }
          } else if (index === selectedOption) {
            btnStateClass = 'option-btn-selected';
          }

          return (
            <button
              key={index}
              type="button"
              className={`option-btn ${btnStateClass}`}
              onClick={() => handleSelect(index)}
              disabled={isAnswered}
              aria-pressed={selectedOption === index}
            >
              <span className="option-index">{getOptionLabel(index)}</span>
              <span className="option-text">{option}</span>
            </button>
          );
        })}
      </div>

      {isAnswered && (
        <div className="feedback-card" aria-live="polite">
          {isCorrect ? (
            <div className="feedback-title-correct">
              <span>✓ 正解です！</span>
            </div>
          ) : (
            <div className="feedback-title-wrong">
              <span>✕ 残念、不正解です</span>
            </div>
          )}
          <p className="feedback-explanation">{question.explanation}</p>

          <button
            ref={nextButtonRef}
            type="button"
            className="next-btn"
            onClick={handleNext}
          >
            {currentIndex + 1 === totalCount ? '最終結果を見る' : '次の問題へ進む →'}
          </button>
        </div>
      )}
    </div>
  );
};

export default QuizCard;

import { QuizQuestion, UserAnswer } from '../types';

interface ResultScreenProps {
  score?: number;
  totalCount?: number;
  questions?: QuizQuestion[];
  userAnswers?: UserAnswer[];
  onRetry?: () => void;
}

const getRankInfo = (score: number, total: number) => {
  const percentage = total <= 0 ? 0 : Math.round((score / total) * 100);
  if (percentage === 100) {
    return {
      percentage,
      rank: '称号：日本の地理マスター 🗾✨',
      comment: '全問正解！素晴らしい知識です。日本各地の地形や地理的特徴を完璧に把握していますね！',
    };
  }
  if (percentage >= 80) {
    return {
      percentage,
      rank: '称号：地理エキスパート 🌲',
      comment: '惜しくも満点には届きませんでしたが、日本地理のハイレベルな知識を持っています！',
    };
  }
  if (percentage >= 60) {
    return {
      percentage,
      rank: '称号：地理トラベラー 🗺️',
      comment: '半分以上正解です！基本的な日本の名所や特徴をしっかりと押さえられています。',
    };
  }
  if (percentage >= 40) {
    return {
      percentage,
      rank: '称号：地理探訪者 🧭',
      comment: 'ここからがスタート！下の振り返り解説を読んで、次回は全問正解を目指しましょう。',
    };
  }
  return {
    percentage,
    rank: '称号：地理ビギナー 🎒',
    comment: '日本にはまだまだ面白い地理の知識がたくさんあります。解説をチェックして再挑戦してみましょう！',
  };
};

const ResultScreen = ({
  score = 0,
  totalCount = 5,
  questions = [],
  userAnswers = [],
  onRetry,
}: ResultScreenProps) => {
  const rankInfo = getRankInfo(score, totalCount);

  const handleRetry = () => {
    if (onRetry) {
      onRetry();
    }
  };

  return (
    <div className="result-card">
      <div className="score-badge">
        <span className="score-number">{score}</span>
        <span className="score-max">/ {totalCount}問正解 ({rankInfo.percentage}%)</span>
      </div>

      <div className="score-rank">{rankInfo.rank}</div>
      <p className="score-comment">{rankInfo.comment}</p>

      <button type="button" className="retry-btn" onClick={handleRetry}>
        <span>↻ もう一度挑戦する</span>
      </button>

      <section className="review-section">
        <h3 className="review-heading">全問の振り返りと解説</h3>
        {questions.map((q, index) => {
          const userAns = userAnswers.find((ans) => ans.questionId === q.id);
          const isCorrect = userAns ? userAns.isCorrect : false;
          const userOptionText =
            userAns && userAns.selectedIndex >= 0
              ? q.options[userAns.selectedIndex]
              : '未回答';
          const correctOptionText = q.options[q.answerIndex];

          return (
            <div key={q.id} className="review-item">
              <div className="review-q-title">
                問{index + 1}. {q.question}
              </div>

              <div className="review-ans-info">
                {isCorrect ? (
                  <div className="review-correct-text">
                    <span>【正解】</span>
                    <span>✓ あなたの回答: {userOptionText}</span>
                  </div>
                ) : (
                  <div className="review-wrong-text">
                    <span>【不正解】</span>
                    <span>✕ あなたの回答: {userOptionText}（正解: {correctOptionText}）</span>
                  </div>
                )}
              </div>

              <p className="review-desc">{q.explanation}</p>
            </div>
          );
        })}
      </section>
    </div>
  );
};

export default ResultScreen;

import { useState, useEffect, useCallback } from 'react';
import { quizQuestions } from './data/quizData';
import { UserAnswer } from './types';
import QuizCard from './components/QuizCard';
import ResultScreen from './components/ResultScreen';

const HIGH_SCORE_KEY = 'japan_geography_quiz_high_score';

const App = () => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);
  const [userAnswers, setUserAnswers] = useState<UserAnswer[]>([]);
  const [isCompleted, setIsCompleted] = useState(false);
  const [highScore, setHighScore] = useState<number | null>(() => {
    try {
      const saved = localStorage.getItem(HIGH_SCORE_KEY);
      return saved !== null ? parseInt(saved, 10) : null;
    } catch {
      return null;
    }
  });

  const totalCount = quizQuestions.length;
  const currentQuestion = quizQuestions[currentIndex];

  const handleSelectOption = useCallback(
    (index: number) => {
      if (isAnswered || !currentQuestion) return;

      setSelectedOption(index);
      setIsAnswered(true);

      const isCorrect = index === currentQuestion.answerIndex;
      const newAnswer: UserAnswer = {
        questionId: currentQuestion.id,
        selectedIndex: index,
        isCorrect,
      };

      setUserAnswers((prev) => [...prev, newAnswer]);
    },
    [isAnswered, currentQuestion]
  );

  const handleNext = useCallback(() => {
    if (currentIndex + 1 < totalCount) {
      setCurrentIndex((prev) => prev + 1);
      setSelectedOption(null);
      setIsAnswered(false);
    } else {
      setIsCompleted(true);
      const currentScore = userAnswers.filter((ans) => ans.isCorrect).length;
      setHighScore((prev) => {
        const nextHigh = prev === null ? currentScore : Math.max(prev, currentScore);
        try {
          localStorage.setItem(HIGH_SCORE_KEY, String(nextHigh));
        } catch {
          // ignore localStorage error
        }
        return nextHigh;
      });
    }
  }, [currentIndex, totalCount, userAnswers]);

  const handleRetry = useCallback(() => {
    setCurrentIndex(0);
    setSelectedOption(null);
    setIsAnswered(false);
    setUserAnswers([]);
    setIsCompleted(false);
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (isCompleted) {
        if (e.key === 'Enter') {
          handleRetry();
        }
        return;
      }

      if (!isAnswered && currentQuestion) {
        if (['1', '2', '3', '4'].includes(e.key)) {
          const index = parseInt(e.key, 10) - 1;
          if (index >= 0 && index < currentQuestion.options.length) {
            handleSelectOption(index);
          }
        }
      } else if (isAnswered) {
        if (e.key === 'Enter') {
          handleNext();
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isCompleted, isAnswered, currentQuestion, handleSelectOption, handleNext, handleRetry]);

  const answeredCount = isCompleted
    ? totalCount
    : currentIndex + (isAnswered ? 1 : 0);
  const progressPercent = Math.round((answeredCount / totalCount) * 100);
  const score = userAnswers.filter((ans) => ans.isCorrect).length;

  return (
    <div className="quiz-app">
      <div className="quiz-container">
        <header className="quiz-header">
          <h1 className="header-title">
            <span>🗾 日本の地理クイズ</span>
          </h1>

          <div className="progress-wrapper">
            <div className="progress-bar-bg">
              <div
                className="progress-bar-fill"
                style={{ width: `${progressPercent}%` }}
              />
            </div>
            <div className="progress-counter">
              <span>{isCompleted ? '全問回答完了' : `第 ${currentIndex + 1} 問`}</span>
              <span>
                進捗: {answeredCount} / {totalCount} 問
                {highScore !== null ? ` (最高記録: ${highScore}/${totalCount})` : ''}
              </span>
            </div>
          </div>
        </header>

        <main>
          {!isCompleted && currentQuestion ? (
            <QuizCard
              question={currentQuestion}
              currentIndex={currentIndex}
              totalCount={totalCount}
              selectedOption={selectedOption}
              isAnswered={isAnswered}
              onSelectOption={handleSelectOption}
              onNext={handleNext}
            />
          ) : (
            <ResultScreen
              score={score}
              totalCount={totalCount}
              questions={quizQuestions as unknown as import('./types').QuizQuestion[]}
              userAnswers={userAnswers}
              onRetry={handleRetry}
            />
          )}
        </main>
      </div>
    </div>
  );
};

export default App;
